const data = $input.first().json.data;
const voos = [];

const cias = {
  'LA': 'LATAM', 'JJ': 'LATAM Brasil', 'G3': 'Gol', 'AD': 'Azul',
  'AA': 'American', 'UA': 'United', 'DL': 'Delta', 'AF': 'Air France',
  'KL': 'KLM', 'LH': 'Lufthansa', 'TP': 'TAP', 'IB': 'Iberia',
  'CM': 'Copa', 'AV': 'Avianca', 'AR': 'Aerolíneas', 'H2': 'Sky',
  'EK': 'Emirates', 'QR': 'Qatar', 'TK': 'Turkish', 'BA': 'British'
};

for (const [destino, opcoes] of Object.entries(data)) {
  for (const [escalas, voo] of Object.entries(opcoes)) {
    voos.push({
      destino: destino,
      escalas: Number(escalas),
      preco: voo.price,
      companhia: voo.airline,
      ida: voo.departure_at,
      volta: voo.return_at
    });
  }
}

voos.sort((a, b) => a.preco - b.preco);

const baratas = voos.filter(v => {
  const ida = v.ida.slice(0, 10);
  return (ida === '2027-05-14' || ida === '2027-05-15') && v.preco < 9000;
});

const agoraSP = new Date().toLocaleString('en-US', { timeZone: 'America/Sao_Paulo' });
const hora = new Date(agoraSP).getHours();
const carimbo = new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' });

if (baratas.length === 0) {
  if (hora !== 0) {
    return [];
  }
  return [{ json: { corpo: `
    <div style="font-family:Arial,sans-serif;max-width:600px;">
      <h2 style="color:#111827;">Porto Alegre → Amsterdã</h2>
      <div style="padding:12px 16px;background:#f9fafb;border-left:4px solid #9ca3af;border-radius:6px;">
        <p style="color:#6b7280;font-size:14px;margin:0;">
          Nenhuma passagem encontrada para 14 ou 15 de maio de 2027.
        </p>
      </div>
      <p style="color:#9ca3af;font-size:12px;margin-top:20px;">
        Verificado em ${carimbo} — o monitor está funcionando.
      </p>
    </div>` } }];
}

const linhas = baratas.map((v, i) => {
  const idaISO = v.ida.slice(0, 10);
  const voltaISO = v.volta.slice(0, 10);
  const ida = idaISO.split('-').reverse().join('/');
  const volta = voltaISO.split('-').reverse().join('/');

  const linkAvia = `https://search.aviasales.com/flights/?origin_iata=POA&destination_iata=AMS&depart_date=${idaISO}&return_date=${voltaISO}&adults=1&one_way=false`;
  const d1 = idaISO.slice(2).replace(/-/g, '');
  const d2 = voltaISO.slice(2).replace(/-/g, '');
  const linkSky = `https://www.skyscanner.com.br/transporte/passagens-aereas/poa/ams/${d1}/${d2}/`;

  const escalas = v.escalas === 0 ? 'Direto' : `${v.escalas} escala(s)`;
  const destaque = i === 0 ? 'border-left:4px solid #16a34a;' : 'border-left:4px solid #e5e7eb;';
  const cia = cias[v.companhia] || v.companhia;

  return `
    <div style="${destaque}padding:12px 16px;margin-bottom:12px;background:#f9fafb;border-radius:6px;">
      <div style="font-size:18px;font-weight:600;color:#111827;">
        Amsterdã — <span style="color:#16a34a;">R$ ${v.preco}</span>
      </div>
      <div style="font-size:14px;color:#6b7280;margin:6px 0;">
        ${ida} → ${volta} &nbsp;•&nbsp; ${escalas} &nbsp;•&nbsp; ${cia}
      </div>
      <a href="${linkSky}" style="display:inline-block;background:#2563eb;color:#fff;padding:8px 16px;border-radius:4px;text-decoration:none;font-size:14px;margin-right:8px;">Skyscanner</a>
      <a href="${linkAvia}" style="display:inline-block;background:#6b7280;color:#fff;padding:8px 16px;border-radius:4px;text-decoration:none;font-size:14px;">Aviasales</a>
    </div>`;
}).join('');

const texto = `
  <div style="font-family:Arial,sans-serif;max-width:600px;">
    <h2 style="color:#111827;">Porto Alegre → Amsterdã</h2>
    <p style="color:#6b7280;font-size:14px;">Saídas em 14 ou 15 de maio de 2027.</p>
    ${linhas}
    <p style="color:#9ca3af;font-size:12px;margin-top:20px;">
      Verificado em ${carimbo} — preços do cache da Aviasales, confirme no site antes de comprar.
    </p>
  </div>`;

return [{ json: { corpo: texto } }];
